require_once dirname(__DIR__).'/config/config.php';
require_once ROOT_PATH.'/includes/functions.php';
$term=trim((string)($_GET['q']??'')); $location=trim((string)($_GET['location']??'')); $verified=!empty($_GET['verified']); $sort=(string)($_GET['sort']??'relevance'); $suppliers=[]; $error=null;
try{$suppliers=(new Supplier())->search($term,$location,$verified,0,$sort,40);}catch(PDOException $e){error_log('B2B suppliers: '.$e->getMessage());$error='Supplier directory is temporarily unavailable.';}
