<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Find suppliers - <?=e(SITE_NAME)?></title><link rel="stylesheet" href="<?=e(BASE_URL)?>/assets/css/style.css"></head><body class="b2b-page"><header class="directory-header"><div class="container directory-header-row"><a class="brand" href="<?=e(BASE_URL)?>/b2b/"><span class="brand-mark">Q</span><span><strong>QUINCY</strong><small>BUSINESS</small></span></a><nav><a href="<?=e(BASE_URL)?>/b2b/marketplace.php">Marketplace</a><a class="directory-active" href="<?=e(BASE_URL)?>/b2b/suppliers.php">Suppliers</a><a href="<?=e(BASE_URL)?>/b2b/quotations.php">My RFQs</a><a href="<?=e(BASE_URL)?>/b2b/negotiations.php">Negotiations</a></nav></div></header><main class="container b2b-main"><div class="directory-breadcrumb"><a href="<?=e(BASE_URL)?>/b2b/">Workspace</a><span>/</span>Find suppliers</div><section class="b2b-hero"><div><p class="eyebrow">SUPPLIER DIRECTORY</p><h1>Build reliable sourcing relationships.</h1><p>Discover active suppliers and connect with businesses ready to fulfil your next order.</p></div></section><form class="b2b-search" method="get"><label><span>Supplier, product, or city</span><input name="q" value="<?=e($term)?>" placeholder="Search suppliers"></label><label><span>Location</span><input name="location" value="<?=e($location)?>" placeholder="Country or city"></label><label class="checkbox-field"><input type="checkbox" name="verified" value="1" <?=$verified?'checked':''?>> Verified only</label><button class="button button-primary">Search</button></form><?php if($error):?><div class="catalog-notice"><?=e($error)?></div><?php elseif(!$suppliers):?><div class="supplier-empty"><h2>No suppliers found</h2><p>Try a broader search or post an RFQ for supplier responses.</p><a href="<?=e(BASE_URL)?>/b2b/request-quotation.php">Post an RFQ</a></div><?php else:?><div class="supplier-grid"><?php foreach($suppliers as $s):?><article class="supplier-card"><div class="supplier-detail-heading"><span class="supplier-mini-avatar"><?=e(strtoupper(substr((string)$s['supplier_name'],0,1)))?></span><div><h2><?=e($s['supplier_name'])?></h2><p><?=e(implode(', ',array_filter([$s['city'],$s['country']])))?></p></div></div><?php if($s['verification_status']==='verified'):?><span class="verified-badge">Verified supplier</span><?php endif;?><p><?=e($s['description']?:'Business supplier on Quincy Store.')?></p><div class="supplier-detail-metrics"><span><strong><?=number_format((float)($s['rating']??0),1)?></strong> ★ rating</span><span><?= (int)$s['product_count']?> active products</span></div><a class="button outline-button" href="<?=e(BASE_URL)?>/b2b/products.php?supplier=<?= (int)$s['id']?>">View products</a></article><?php endforeach;?></div><?php endif;?></main></body></html>